/**
 * Projectile Motion simulation.
 *
 * vx0 = v0*cos(theta), vy0 = v0*sin(theta)
 * x(t)  = vx0*t
 * y(t)  = y0 + vy0*t - (1/2)*g*t^2
 *
 * Always computed here, in code -- never fetched from a server and never
 * generated by AI. Mirrors apps/physics/simulations_projectile.py exactly
 * (same bounds, same formulas, same un-clamped-at-the-ground evaluation of
 * the closed-form equations), the same way kinematics.js mirrors
 * apps/physics/simulations_kinematics.py. This file owns its own physics,
 * SVG and controls; it shares only the run-loop/registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var MIN_V0_MS = 0.0;
  var MAX_V0_MS = 40.0;
  var MIN_ANGLE_DEG = 0.0;
  var MAX_ANGLE_DEG = 90.0;
  var MIN_H0_M = 0.0;
  var MAX_H0_M = 50.0;
  var MAX_TIME_S = 12.0;
  var GRAVITY_MS2 = 9.8;

  function clampV0(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_V0_MS, Math.min(MAX_V0_MS, n));
  }
  function clampAngle(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_ANGLE_DEG, Math.min(MAX_ANGLE_DEG, n));
  }
  function clampH0(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_H0_M, Math.min(MAX_H0_M, n));
  }

  function computeState(v0, angleDeg, h0, t) {
    v0 = clampV0(v0);
    angleDeg = clampAngle(angleDeg);
    h0 = clampH0(h0);
    t = Math.max(0, Math.min(MAX_TIME_S, Number(t)));
    var theta = (angleDeg * Math.PI) / 180;
    var vx0 = v0 * Math.cos(theta);
    var vy0 = v0 * Math.sin(theta);
    var x = vx0 * t;
    var y = h0 + vy0 * t - 0.5 * GRAVITY_MS2 * t * t;
    var vx = vx0;
    var vy = vy0 - GRAVITY_MS2 * t;
    return { x: x, y: y, vx: vx, vy: vy, speed: Math.hypot(vx, vy) };
  }

  // Time (from a standing start) for the projectile to return to y=0, and the
  // greatest height it reaches -- used only to size the SVG scene sensibly
  // for the current inputs, never fed back into the physics itself.
  function flightTime(v0, angleDeg, h0) {
    var theta = (angleDeg * Math.PI) / 180;
    var vy0 = v0 * Math.sin(theta);
    var disc = vy0 * vy0 + 2 * GRAVITY_MS2 * h0;
    if (disc < 0) return 0.5;
    return Math.max((vy0 + Math.sqrt(disc)) / GRAVITY_MS2, 0.5);
  }
  function apexHeight(v0, angleDeg, h0) {
    var theta = (angleDeg * Math.PI) / 180;
    var vy0 = v0 * Math.sin(theta);
    return vy0 > 0 ? h0 + (vy0 * vy0) / (2 * GRAVITY_MS2) : Math.max(h0, 0.1);
  }

  // Geometry constants for the SVG scene/graph.
  var ORIGIN_X_PX = 36;
  var GROUND_Y_PX = 250;
  var USABLE_W_PX = 580;
  var USABLE_H_PX = 220;
  var MIN_SCALE = 2; // px per metre
  var MAX_SCALE = 40;
  var REDUCED_MOTION_STOP_S = 6;
  var STEP_S = 0.25;

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }
  function round4(n) {
    return Math.round(n * 10000) / 10000;
  }

  function createProjectileSim(root, config, lab) {
    var state = {
      v0: clampV0(readNum(root, "v0", 15)),
      angle: clampAngle(readNum(root, "angle", 45)),
      h0: clampH0(readNum(root, "h0", 0)),
      timeS: 0,
      x: 0,
      y: 0,
      speed: 0,
      scale: 10
    };

    var trace = []; // [t, y] samples, feeds the height-vs-time graph
    var maxAbsY = 1;

    var el = {
      scene: root.querySelector("[data-lab-scene]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      marker: root.querySelector("[data-cart]"),
      path: root.querySelector("[data-traj-path]"),
      ground: root.querySelector("[data-ground-line]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      trace: root.querySelector("[data-lab-trace]"),
      valueV0: root.querySelector("[data-value-speed]"),
      valueAngle: root.querySelector("[data-value-angle]"),
      valueHeight: root.querySelector("[data-value-height]"),
      valueTime: root.querySelector("[data-value-time]"),
      valueX: root.querySelector("[data-value-x]"),
      valueY: root.querySelector("[data-value-y]"),
      eqX: root.querySelector("[data-eq-x]"),
      eqY: root.querySelector("[data-eq-y]"),
      outV0: root.querySelector("[data-out-speed]"),
      outAngle: root.querySelector("[data-out-angle]"),
      inputV0: root.querySelector("[data-input-speed]"),
      inputAngle: root.querySelector("[data-input-angle]"),
      inputHeight: root.querySelector("[data-input-height]"),
      outHeight: root.querySelector("[data-out-height]"),
      btnStart: root.querySelector("[data-action-start]"),
      btnPause: root.querySelector("[data-action-pause]"),
      btnReset: root.querySelector("[data-action-reset]"),
      btnStep: root.querySelector("[data-action-step]"),
      inputTime: root.querySelector("[data-input-time]"),
      outTime: root.querySelector("[data-out-time]"),
      motionNote: root.querySelector("[data-motion-note]")
    };

    var loop = lab.createRunLoop(tick, {});

    function updateScale() {
      var tLand = flightTime(state.v0, state.angle, state.h0);
      var theta = (state.angle * Math.PI) / 180;
      var xRange = Math.max(state.v0 * Math.cos(theta) * tLand, 1);
      var yRange = Math.max(apexHeight(state.v0, state.angle, state.h0), 1);
      var scale = Math.min(USABLE_W_PX / xRange, USABLE_H_PX / yRange);
      state.scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, scale));
    }

    function screenX(xM) {
      return ORIGIN_X_PX + xM * state.scale;
    }
    function screenY(yM) {
      return GROUND_Y_PX - yM * state.scale;
    }

    function recordTrace() {
      trace.push([round4(state.timeS), round4(state.y)]);
      maxAbsY = Math.max(maxAbsY, Math.abs(state.y));
    }

    function setV0(value) {
      state.v0 = clampV0(value);
      if (el.inputV0) el.inputV0.value = String(state.v0);
      if (el.outV0) el.outV0.textContent = String(state.v0);
      updateScale();
      setTime(0);
    }
    function setAngle(value) {
      state.angle = clampAngle(value);
      if (el.inputAngle) el.inputAngle.value = String(state.angle);
      if (el.outAngle) el.outAngle.textContent = String(state.angle);
      updateScale();
      setTime(0);
    }
    function setHeight(value) {
      state.h0 = clampH0(value);
      if (el.inputHeight) el.inputHeight.value = String(state.h0);
      if (el.outHeight) el.outHeight.textContent = String(state.h0);
      updateScale();
      setTime(0);
    }

    function start() {
      loop.start();
    }
    function pause() {
      loop.stop();
    }
    function reset() {
      loop.stop();
      setTime(0);
    }

    function rebuildTrace(upToT) {
      trace = [];
      maxAbsY = Math.max(1, Math.abs(state.h0));
      var sampleDt = Math.max(upToT / 40, 0.05);
      for (var t = 0; t < upToT - 1e-9; t += sampleDt) {
        var c = computeState(state.v0, state.angle, state.h0, t);
        trace.push([round4(t), round4(c.y)]);
        maxAbsY = Math.max(maxAbsY, Math.abs(c.y));
      }
      trace.push([round4(upToT), round4(state.y)]);
      maxAbsY = Math.max(maxAbsY, Math.abs(state.y));
    }

    function setTime(value) {
      loop.stop();
      var t = Number(value);
      if (!isFinite(t)) return;
      t = Math.max(0, Math.min(MAX_TIME_S, t));
      var computed = computeState(state.v0, state.angle, state.h0, t);
      state.timeS = t;
      state.x = computed.x;
      state.y = computed.y;
      state.speed = computed.speed;
      rebuildTrace(t);
      if (el.sceneStatus) {
        el.sceneStatus.textContent = computed.y < 0 ? "Below the launch height." : "";
      }
      render();
    }

    function stepForward() {
      setTime(state.timeS + STEP_S);
    }

    function tick(dt) {
      if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        return;
      }
      var nextT = Math.min(MAX_TIME_S, state.timeS + dt);
      var computed = computeState(state.v0, state.angle, state.h0, nextT);
      state.timeS = nextT;
      state.x = computed.x;
      state.y = computed.y;
      state.speed = computed.speed;
      recordTrace();

      if (computed.y < 0) {
        loop.stop();
        if (el.sceneStatus) el.sceneStatus.textContent = "Reached the ground.";
      } else if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        if (el.sceneStatus) {
          el.sceneStatus.textContent = "Reached the end of the simulated time window (12 s).";
        }
      } else if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
      }
      render();
    }

    function renderTrajectoryPath() {
      if (!el.path) return;
      var tLand = flightTime(state.v0, state.angle, state.h0);
      var points = [];
      var samples = 40;
      for (var i = 0; i <= samples; i++) {
        var t = (tLand * i) / samples;
        var c = computeState(state.v0, state.angle, state.h0, t);
        points.push(screenX(c.x).toFixed(1) + "," + screenY(c.y).toFixed(1));
      }
      el.path.setAttribute("points", points.join(" "));
    }

    function renderScene() {
      if (el.marker) {
        el.marker.setAttribute(
          "transform",
          "translate(" + screenX(state.x).toFixed(1) + "," + screenY(state.y).toFixed(1) + ")"
        );
      }
      if (el.ground) {
        el.ground.setAttribute("y1", String(screenY(0)));
        el.ground.setAttribute("y2", String(screenY(0)));
      }
      renderTrajectoryPath();
      var text =
        "A projectile launched at " + state.v0.toFixed(1) + " metres per second, " +
        state.angle.toFixed(0) + " degrees above the horizontal, from " +
        state.h0.toFixed(1) + " metres up. At " + state.timeS.toFixed(1) +
        " seconds it is " + state.x.toFixed(1) + " metres across and " +
        state.y.toFixed(1) + " metres high.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.trace) return;
      var w = 348, h = 156, left = 40, top = 10, bottom = 6;
      var tMax = Math.max(1, state.timeS);
      var yMax = Math.max(1, maxAbsY);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var px = left + (trace[i][0] / tMax) * (w - left - 12);
        var py = h - bottom - ((trace[i][1] + yMax) / (2 * yMax)) * (h - top - bottom);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      var graphText =
        "Height vs time. At " + state.timeS.toFixed(1) + " seconds the height is " +
        state.y.toFixed(2) + " metres.";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueV0) el.valueV0.textContent = String(state.v0);
      if (el.valueAngle) el.valueAngle.textContent = String(state.angle);
      if (el.valueHeight) el.valueHeight.textContent = state.h0.toFixed(1);
      if (el.valueTime) el.valueTime.textContent = state.timeS.toFixed(2);
      if (el.valueX) el.valueX.textContent = state.x.toFixed(2);
      if (el.valueY) el.valueY.textContent = state.y.toFixed(2);
      if (el.eqX) el.eqX.textContent = state.x.toFixed(2);
      if (el.eqY) el.eqY.textContent = state.y.toFixed(2);
      if (el.inputTime && document.activeElement !== el.inputTime) {
        el.inputTime.value = String(round4(state.timeS));
      }
      if (el.outTime) el.outTime.textContent = state.timeS.toFixed(1);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        initialSpeedMs: state.v0,
        launchAngleDeg: state.angle,
        initialHeightM: state.h0,
        timeS: state.timeS,
        positionXM: state.x,
        positionYM: state.y,
        speedMs: state.speed,
        running: loop.isRunning()
      };
    }

    if (el.inputV0) {
      el.inputV0.addEventListener("input", function () { setV0(el.inputV0.value); });
      el.inputV0.addEventListener("change", function () { setV0(el.inputV0.value); });
    }
    if (el.inputAngle) {
      el.inputAngle.addEventListener("input", function () { setAngle(el.inputAngle.value); });
      el.inputAngle.addEventListener("change", function () { setAngle(el.inputAngle.value); });
    }
    if (el.inputHeight) {
      el.inputHeight.addEventListener("input", function () { setHeight(el.inputHeight.value); });
      el.inputHeight.addEventListener("change", function () { setHeight(el.inputHeight.value); });
    }
    if (el.btnStart) el.btnStart.addEventListener("click", start);
    if (el.btnPause) el.btnPause.addEventListener("click", pause);
    if (el.btnReset) el.btnReset.addEventListener("click", reset);
    if (el.btnStep) el.btnStep.addEventListener("click", stepForward);
    if (el.inputTime) {
      el.inputTime.addEventListener("input", function () { setTime(el.inputTime.value); });
      el.inputTime.addEventListener("change", function () { setTime(el.inputTime.value); });
    }

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    updateScale();
    reset();

    var api = {
      setInitialSpeed: setV0,
      setLaunchAngle: setAngle,
      setInitialHeight: setHeight,
      start: start,
      pause: pause,
      reset: reset,
      setTime: setTime,
      step: stepForward,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("projectile_motion", createProjectileSim);

  PhysicsLab.Projectile = {
    MIN_V0_MS: MIN_V0_MS,
    MAX_V0_MS: MAX_V0_MS,
    MIN_ANGLE_DEG: MIN_ANGLE_DEG,
    MAX_ANGLE_DEG: MAX_ANGLE_DEG,
    MIN_H0_M: MIN_H0_M,
    MAX_H0_M: MAX_H0_M,
    MAX_TIME_S: MAX_TIME_S,
    GRAVITY_MS2: GRAVITY_MS2,
    clampV0: clampV0,
    clampAngle: clampAngle,
    clampH0: clampH0,
    computeState: computeState
  };
})(window, document);
